create or replace function public.jdvcrm_create_warehouse_v1(p_organization_id uuid,p_code text,p_name text,p_address text default null,p_city text default null,p_country text default 'Bénin') returns jsonb language plpgsql security definer set search_path=public,private as $$ declare v_uid uuid:=auth.uid(); v_id uuid; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if not private.is_org_admin(p_organization_id) then raise exception 'ADMIN_ACCESS_REQUIRED'; end if; if not private.is_super_admin() and not private.has_active_subscription(p_organization_id) then raise exception 'SUBSCRIPTION_REQUIRED'; end if; if nullif(trim(p_code),'') is null then raise exception 'WAREHOUSE_CODE_REQUIRED'; end if; if nullif(trim(p_name),'') is null then raise exception 'WAREHOUSE_NAME_REQUIRED'; end if; if nullif(trim(p_city),'') is null then raise exception 'WAREHOUSE_CITY_REQUIRED'; end if; insert into public.warehouses(organization_id,code,name,address,city,country,active) values(p_organization_id,trim(p_code),trim(p_name),nullif(trim(p_address),''),trim(p_city),coalesce(nullif(trim(p_country),''),'Bénin'),true) returning id into v_id; return jsonb_build_object('success',true,'warehouse_id',v_id); exception when unique_violation then raise exception 'WAREHOUSE_ALREADY_EXISTS'; end; $$; revoke all on function public.jdvcrm_create_warehouse_v1(uuid,text,text,text,text,text) from public,anon; grant execute on function public.jdvcrm_create_warehouse_v1(uuid,text,text,text,text,text) to authenticated;